(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-801":{scenario:{company:"Lam Tuyền Wellness Retreat",supervisor:{name:"Đỗ Thu Hà",role:{vi:"Giám đốc Vận hành Khu nghỉ dưỡng",en:"Resort Operations Director"}},ref_code:"SPA-2715",title:{vi:"Đúng liệu trình. Đúng chỉ số. Đúng an toàn cho khách.",en:"Right treatment. Right metric. Right guest safety."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát báo cáo tuần SPA-2715. Spa có 6 phòng trị liệu, mở 10 giờ/ngày, 7 ngày; tuần qua bán 294 giờ trị liệu, doanh thu trị liệu 147.000.000 VND (số liệu mô phỏng). Phiếu sàng lọc sức khỏe của một khách ghi đang mang thai 20 tuần nhưng lịch đặt là massage đá nóng. Đối chiếu bản nháp với quy trình đã duyệt, sửa liệu trình phù hợp và chỉ số RevPATH (VND), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing weekly report SPA-2715. The spa has 6 treatment rooms, open 10 hours a day, 7 days a week; last week it sold 294 treatment hours with treatment revenue of 147,000,000 VND (training data). One guest's health screening form shows she is 20 weeks pregnant, yet she is booked for a hot stone massage. Compare the draft with the approved procedures, correct the treatment and the RevPATH metric (VND), then write an evidence-based report."},reference_title:{vi:"Quy trình sàng lọc & bảng chỉ số vận hành đã duyệt · SPA-2715",en:"Approved screening procedure & operating metrics sheet · SPA-2715"},fields:[{id:"TREATMENT",label:{vi:"Liệu trình xếp cho khách mang thai",en:"Treatment booked for the pregnant guest"},initial:"HOT-STONE",expected:"PRENATAL",choices:["HOT-STONE","DEEP-TISSUE","PRENATAL"],reference:"Bảng chống chỉ định liệu trình",hint:{vi:"Đọc phiếu sàng lọc trước khi xác nhận lịch: thai kỳ là chống chỉ định với liệu pháp nhiệt cao và tác động sâu.",en:"Read the screening form before confirming: pregnancy contraindicates high-heat and deep-pressure therapies."}},{id:"REVPATH",label:{vi:"Doanh thu trên giờ trị liệu khả dụng (VND)",en:"Revenue per available treatment hour (VND)"},initial:"500000",expected:"350000",reference:"Bảng chỉ số vận hành tuần",ref_value:{vi:"6 phòng x 10 giờ/ngày x 7 ngày; doanh thu trị liệu 147.000.000 VND",en:"6 rooms x 10 hours/day x 7 days; treatment revenue 147,000,000 VND"},hint:{vi:"Mẫu số của RevPATH là toàn bộ giờ có thể bán, không phải số giờ đã bán.",en:"The RevPATH denominator is all sellable hours, not the hours actually sold."}}],sop32:{vi:"RevPATH = doanh thu trị liệu / tổng giờ trị liệu khả dụng; giờ khả dụng = số phòng trị liệu x giờ mở cửa mỗi ngày x số ngày mở cửa trong kỳ.",en:"RevPATH = treatment revenue / total available treatment hours; available hours = treatment rooms x opening hours per day x opening days in the period."},context:{label:"SPA PMS / SPA-2715",metrics:[{label:{vi:"Phòng trị liệu",en:"Treatment rooms"},value:"6"},{label:{vi:"Giờ trị liệu đã bán",en:"Treatment hours sold"},value:"294"},{label:{vi:"Doanh thu trị liệu tuần",en:"Weekly treatment revenue"},value:"147,000,000 VND"}]},crisis:{vi:"Khách VIP nhất quyết muốn massage đá nóng đúng gói đã mua. Trưởng ca nói: “Cho khách ký giấy miễn trách nhiệm rồi cứ làm, đổi gói là mất doanh thu. Kỹ thuật viên chưa có chứng chỉ massage bầu cũng được.”",en:"A VIP guest insists on the hot stone massage in her package. The shift leader says: “Have her sign a waiver and just do it, changing the package loses revenue. A therapist without prenatal certification is fine.”"},options:{safe:{vi:"Từ chối liệu trình chống chỉ định dù có giấy miễn trách nhiệm, giải thích tế nhị, đề xuất massage bầu do kỹ thuật viên có chứng chỉ thực hiện, ghi hồ sơ và báo Giám đốc Vận hành.",en:"Decline the contraindicated treatment even with a waiver, explain tactfully, offer prenatal massage by a certified therapist, record it and inform the Operations Director."},shortcut:{vi:"Cho khách ký giấy miễn trách nhiệm và làm massage đá nóng để giữ doanh thu.",en:"Have the guest sign a waiver and perform the hot stone massage to keep the revenue."},wait:{vi:"Để kỹ thuật viên tự quyết định khi khách vào phòng trị liệu.",en:"Let the therapist decide when the guest arrives in the treatment room."}},questions:{vi:["Vì sao chuyển sang PRENATAL và RevPATH đúng là 350000 VND? Trình bày căn cứ từ phiếu sàng lọc và cách tính.","Vì sao giấy miễn trách nhiệm không thay thế được sàng lọc chống chỉ định? Bạn bảo vệ khách và spa thế nào?"],en:["Why switch to PRENATAL, and why is the correct RevPATH 350000 VND? Show the screening evidence and the calculation.","Why can a waiver not replace contraindication screening? How do you protect both the guest and the spa?"]},hints:{vi:["Đặt lịch đặt nháp cạnh bảng chống chỉ định và khoanh dòng thai kỳ.","Áp dụng SOP mục 3.2: tính giờ khả dụng từ số phòng, giờ mở cửa và số ngày trước khi chia doanh thu.","Đọc lại SOP mục 4.2: liệu trình chống chỉ định không được thực hiện vì áp lực doanh thu; phải báo cáo người có thẩm quyền."],en:["Place the draft booking next to the contraindication table and circle the pregnancy line.","Apply SOP 3.2: compute available hours from rooms, opening hours and days before dividing revenue.","Re-read SOP 4.2: contraindicated treatments are never performed under revenue pressure; escalate to the person in charge."]}},learning:{summary:{vi:"Quản lý spa và chăm sóc sức khỏe điều hành toàn bộ khu trị liệu: thiết kế thực đơn liệu trình, sàng lọc chống chỉ định, quản lý kỹ thuật viên, lịch phòng, vệ sinh khử khuẩn, sản phẩm và doanh thu. Mục tiêu là trải nghiệm thư giãn an toàn, nhất quán và hiệu quả kinh doanh, dựa trên kỷ luật quy trình, hiểu biết giới hạn của dịch vụ không phải y khoa và kỹ năng tư vấn tận tâm.",en:"A spa and wellness manager runs the whole treatment area: designing the treatment menu, contraindication screening, managing therapists, room schedules, hygiene and disinfection, products and revenue. The goal is a safe, consistent, relaxing experience with sound business results, based on procedural discipline, awareness of the limits of non-medical services and caring advisory skills."},responsibilities:{vi:["Xây dựng thực đơn liệu trình, quy trình chuẩn từng dịch vụ và bộ phiếu sàng lọc sức khỏe.","Lập lịch kỹ thuật viên và phòng trị liệu để tối ưu công suất mà vẫn bảo đảm thời gian nghỉ.","Giám sát vệ sinh, khử khuẩn dụng cụ, đồ vải, bồn ngâm và quản lý hạn dùng sản phẩm.","Theo dõi doanh thu, RevPATH, tỷ lệ sử dụng phòng, doanh thu bán lẻ và tỷ lệ đặt lại.","Đào tạo kỹ năng, chứng chỉ chuyên môn và xử lý phản hồi, sự cố liên quan đến khách."],en:["Build the treatment menu, standard procedures for each service and health screening forms.","Schedule therapists and treatment rooms to optimize capacity while protecting rest breaks.","Supervise hygiene, disinfection of tools, linen and tubs and manage product expiry.","Track revenue, RevPATH, room utilization, retail sales and rebooking rates.","Train skills, maintain certifications and handle guest feedback and incidents."]},competencies:[{name:{vi:"Sàng lọc & an toàn khách",en:"Screening & guest safety"},desc:{vi:"Đọc phiếu tư vấn, nhận diện chống chỉ định như thai kỳ, huyết áp cao, bệnh da và chuyển hướng liệu trình phù hợp.",en:"Read consultation forms, spot contraindications such as pregnancy, high blood pressure or skin conditions and redirect to suitable treatments."}},{name:{vi:"Quản trị doanh thu spa",en:"Spa revenue management"},desc:{vi:"Dùng RevPATH, tỷ lệ sử dụng phòng và giá theo khung giờ để tối ưu doanh thu.",en:"Use RevPATH, room utilization and time-based pricing to optimize revenue."}},{name:{vi:"Vệ sinh & kiểm soát nhiễm khuẩn",en:"Hygiene & infection control"},desc:{vi:"Thiết lập quy trình làm sạch, khử khuẩn, đồ dùng một lần và kiểm tra định kỳ.",en:"Set cleaning, disinfection and single-use item procedures with regular checks."}},{name:{vi:"Quản lý đội ngũ kỹ thuật viên",en:"Therapist team management"},desc:{vi:"Phân công theo chứng chỉ, kèm cặp kỹ năng và bảo vệ sức khỏe nghề nghiệp của nhân viên.",en:"Assign by certification, coach skills and protect staff occupational health."}},{name:{vi:"Tư vấn & đạo đức nghề",en:"Advisory & professional ethics"},desc:{vi:"Tư vấn trung thực, không hứa hẹn tác dụng chữa bệnh, tôn trọng riêng tư và sự đồng ý của khách.",en:"Advise honestly, never promise medical cures and respect guest privacy and consent."}}],knowledge:{vi:["Phân biệt dịch vụ chăm sóc, thư giãn với khám bệnh, chữa bệnh: thủ thuật xâm lấn chỉ thực hiện tại cơ sở được cấp phép theo Luật Khám bệnh, chữa bệnh số 15/2023/QH15.","Các chống chỉ định phổ biến trong trị liệu: thai kỳ, sốt, huyết áp không kiểm soát, giãn tĩnh mạch, tổn thương da, sau phẫu thuật.","Chỉ số vận hành spa: RevPATH, tỷ lệ sử dụng phòng, tỷ lệ bán lẻ trên dịch vụ và tỷ lệ khách đặt lại.","Nguyên tắc vệ sinh, khử khuẩn dụng cụ dùng chung, đồ vải và nước bồn ngâm theo hướng dẫn của nhà sản xuất và cơ quan y tế.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thông tin sức khỏe của khách là dữ liệu nhạy cảm cần bảo mật."],en:["Distinguish care and relaxation services from medical treatment: invasive procedures belong only in facilities licensed under Medical Examination and Treatment Law No. 15/2023/QH15.","Common treatment contraindications: pregnancy, fever, uncontrolled blood pressure, varicose veins, broken skin and recent surgery.","Spa operating metrics: RevPATH, room utilization, retail-to-service ratio and rebooking rate.","Hygiene and disinfection of shared tools, linen and tub water following manufacturer and health authority guidance.","Current personal data protection rules: guest health information is sensitive data that must be kept confidential."]},tools:["Phần mềm quản lý spa và đặt lịch","Phiếu tư vấn & sàng lọc sức khỏe điện tử","Tủ tiệt trùng dụng cụ","Bảng theo dõi vệ sinh, khử khuẩn","Báo cáo doanh thu và công suất phòng","Hệ thống POS bán lẻ sản phẩm"],kpis:{vi:["RevPATH và tỷ lệ sử dụng phòng trị liệu theo tuần.","Tỷ lệ doanh thu bán lẻ trên doanh thu dịch vụ.","Tỷ lệ khách đặt lại và điểm hài lòng sau liệu trình.","Số sự cố an toàn khách và lỗi bỏ sót sàng lọc (mục tiêu bằng 0)."],en:["Weekly RevPATH and treatment room utilization.","Retail revenue as a share of service revenue.","Rebooking rate and post-treatment satisfaction score.","Guest safety incidents and missed screenings (target zero)."]},day:[{time:"08:30",vi:"Kiểm tra vệ sinh phòng trị liệu, nhiệt độ bồn ngâm, tủ tiệt trùng và hạn dùng sản phẩm.",en:"Check treatment room hygiene, tub temperatures, sterilizers and product expiry dates."},{time:"09:30",vi:"Rà lịch đặt trong ngày, đối chiếu phiếu sàng lọc và phân công kỹ thuật viên theo chứng chỉ.",en:"Review today's bookings, match screening forms and assign therapists by certification."},{time:"12:00",vi:"Tiếp khách VIP, tư vấn liệu trình và giải quyết yêu cầu thay đổi lịch.",en:"Welcome VIP guests, advise on treatments and handle rescheduling requests."},{time:"15:00",vi:"Phân tích RevPATH, công suất khung giờ thấp điểm và đề xuất chương trình ưu đãi.",en:"Analyze RevPATH and off-peak utilization and propose promotions."},{time:"19:00",vi:"Họp cuối ca về phản hồi khách, sự cố và kế hoạch đào tạo tuần tới.",en:"Hold the end-of-shift meeting on guest feedback, incidents and next week's training."}],mistakes:{vi:["Xác nhận lịch theo gói đã bán mà không đọc phiếu sàng lọc, bỏ sót chống chỉ định.","Tính RevPATH bằng doanh thu chia giờ đã bán, làm báo cáo công suất đẹp hơn thực tế.","Dùng giấy miễn trách nhiệm để biện minh cho liệu trình không an toàn."],en:["Confirming bookings from the sold package without reading the screening form, missing contraindications.","Computing RevPATH as revenue divided by sold hours, making capacity look better than it is.","Using a waiver to justify an unsafe treatment."]},career:[{vi:"Kỹ thuật viên trị liệu",en:"Spa therapist"},{vi:"Trưởng ca spa (Spa supervisor)",en:"Spa supervisor"},{vi:"Quản lý spa & chăm sóc sức khỏe",en:"Spa & wellness manager"},{vi:"Giám đốc spa và wellness cụm khu nghỉ dưỡng",en:"Cluster director of spa & wellness"}],glossary:[{term:"RevPATH",vi:"Doanh thu trên mỗi giờ trị liệu khả dụng, đo hiệu quả khai thác công suất spa.",en:"Revenue per available treatment hour, measuring how well spa capacity is monetized."},{term:"Contraindication",vi:"Chống chỉ định: tình trạng khiến một liệu trình có thể gây hại cho khách.",en:"A condition that makes a treatment potentially harmful to the guest."},{term:"Utilization",vi:"Tỷ lệ sử dụng: giờ đã bán chia cho giờ khả dụng của phòng hoặc kỹ thuật viên.",en:"Hours sold divided by available hours of rooms or therapists."},{term:"Retail ratio",vi:"Tỷ lệ doanh thu bán lẻ sản phẩm so với doanh thu dịch vụ trị liệu.",en:"Retail product revenue compared with treatment service revenue."},{term:"Consultation form",vi:"Phiếu tư vấn ghi tình trạng sức khỏe, dị ứng, thai kỳ và mong muốn của khách trước liệu trình.",en:"Pre-treatment form recording health conditions, allergies, pregnancy and guest preferences."}],quiz:[{q:{vi:"Spa có 5 phòng, mở 12 giờ/ngày trong 30 ngày, doanh thu trị liệu 540.000.000 VND. RevPATH là bao nhiêu?",en:"A spa has 5 rooms open 12 hours a day for 30 days with treatment revenue of 540,000,000 VND. What is RevPATH?"},options:{vi:["200.000 VND","250.000 VND","300.000 VND","450.000 VND"],en:["200,000 VND","250,000 VND","300,000 VND","450,000 VND"]},answer:2,explain:{vi:"Giờ khả dụng = 5 x 12 x 30 = 1.800; RevPATH = 540.000.000 / 1.800 = 300.000 VND.",en:"Available hours = 5 x 12 x 30 = 1,800; RevPATH = 540,000,000 / 1,800 = 300,000 VND."}},{q:{vi:"Khách mang thai muốn dùng liệu trình xông hơi nhiệt cao. Bạn xử lý thế nào?",en:"A pregnant guest wants a high-heat sauna treatment. How do you respond?"},options:{vi:["Từ chối tế nhị và đề xuất liệu trình an toàn cho thai kỳ","Đồng ý nếu khách ký cam kết","Giảm thời gian xông còn một nửa","Để khách tự quyết"],en:["Decline tactfully and offer a pregnancy-safe treatment","Agree if the guest signs a waiver","Halve the sauna time","Let the guest decide alone"]},answer:0,explain:{vi:"Nhiệt cao là chống chỉ định trong thai kỳ; an toàn của khách quan trọng hơn doanh thu và giấy cam kết.",en:"High heat is contraindicated in pregnancy; guest safety outweighs revenue and waivers."}},{q:{vi:"Tỷ lệ sử dụng phòng trị liệu được tính như thế nào?",en:"How is treatment room utilization calculated?"},options:{vi:["Doanh thu chia số khách","Số kỹ thuật viên chia số phòng","Giờ khả dụng chia giờ đã bán","Giờ đã bán chia giờ khả dụng"],en:["Revenue divided by guests","Therapists divided by rooms","Available hours divided by sold hours","Sold hours divided by available hours"]},answer:3,explain:{vi:"Tỷ lệ sử dụng = giờ đã bán / giờ khả dụng, cho biết công suất được khai thác bao nhiêu phần trăm.",en:"Utilization = sold hours / available hours, showing the share of capacity in use."}},{q:{vi:"Spa không có giấy phép khám chữa bệnh được phép làm dịch vụ nào?",en:"Which service may a spa without a medical license offer?"},options:{vi:["Tiêm chất làm đầy","Massage thư giãn và chăm sóc da không xâm lấn","Phẫu thuật thẩm mỹ mí mắt","Kê đơn thuốc điều trị mụn"],en:["Dermal filler injections","Relaxation massage and non-invasive skin care","Eyelid cosmetic surgery","Prescribing acne medication"]},answer:1,explain:{vi:"Thủ thuật xâm lấn và kê đơn thuộc hoạt động khám chữa bệnh, chỉ cơ sở được cấp phép mới thực hiện.",en:"Invasive procedures and prescribing are medical activities reserved for licensed facilities."}}],tools_en:["Spa management and booking software","E-consultation & health screening forms","Instrument sterilization cabinet","Hygiene and disinfection log","Revenue and room occupancy reports","POS system for retail products"]}}})})(window.KKR);
